import type {HandoffScope} from './cashier-handoff';
export type DepositTransferSelection={scope:HandoffScope;deposit:string;mapping:string;period:string;date:string;amount:string;custody:string;transit:string};
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v);
function obj(v:unknown):Record<string,unknown>{if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Invalid deposit transfer preview.');return v as Record<string,unknown>}
export function readDepositTransferPreview(value:unknown,s:DepositTransferSelection){
 const v=obj(value),c=obj(v.command);
 if(![...Object.values(s.scope),s.deposit,s.mapping,s.period,s.custody,s.transit].every(uuid)||s.custody===s.transit||!/^\d{4}-\d{2}-\d{2}$/.test(s.date)||Number.isNaN(Date.parse(s.date))||new Date(s.date).toISOString().slice(0,10)!==s.date||! /^[1-9][0-9]{0,11}$/.test(s.amount))throw Error('Invalid deposit selection.');
 if(v.schema_version!==1||v.tenant_id!==s.scope.tenant||v.property_id!==s.scope.property||v.actor_id!==s.scope.actor||v.deposit_id!==s.deposit||v.mapping_id!==s.mapping||v.period_id!==s.period||v.posting_date!==s.date||v.amount_minor!==s.amount||v.sources_reconciled!==true||!Array.isArray(v.blockers)||v.blockers.length!==0||!Array.isArray(v.source_reviews)||v.source_reviews.length===0)throw Error('Deposit preview does not match the selection.');
 for(const source of v.source_reviews){const r=obj(source);if(r.tenant_id!==s.scope.tenant||r.property_id!==s.scope.property||r.actor_id!==s.scope.actor||r.mapping_id!==s.mapping||!uuid(r.session_id)||r.custody_account!==s.custody||r.transit_account!==s.transit||!Array.isArray(r.source_journals))throw Error('Deposit source scope changed.');for(const sourceJournal of r.source_journals){const j=obj(sourceJournal);if(!uuid(j.journal_id)||!uuid(j.source_id)||!['opening','custody','guest_payment'].includes(String(j.kind)))throw Error('Invalid supporting journal.');}}
 if(c.currency!=='USD'||c.description!=='Cash deposit to bank transit'||c.source_kind!=='cashier_bank_deposit'||c.source_id!==s.deposit||c.source_version!==1||c.period_id!==s.period||c.posting_date!==s.date)throw Error('Invalid deposit journal command.');
 for(const lines of [c.lines,v.proposed_lines]){if(!Array.isArray(lines)||lines.length!==2)throw Error('Invalid transfer lines.');const debit=obj(lines[0]),credit=obj(lines[1]);if(debit.account_id!==s.transit||debit.side!=='debit'||debit.amount_minor!==s.amount||credit.account_id!==s.custody||credit.side!=='credit'||credit.amount_minor!==s.amount)throw Error('Deposit transfer accounts or amounts changed.');}
 return v;
}

export type DepositTransferRequest={id:string;selection:DepositTransferSelection;review:Record<string,unknown>};
function checked(r:DepositTransferRequest){if(!uuid(r.id))throw Error('Invalid transfer request.');readDepositTransferPreview(r.review,r.selection);return r}
export function readDepositTransferReceipt(value:unknown,r:DepositTransferRequest){checked(r);const v=obj(value),s=r.selection;if(v.schema_version!==1||v.tenant_id!==s.scope.tenant||v.property_id!==s.scope.property||v.actor_id!==s.scope.actor||v.request_id!==r.id||v.deposit_id!==s.deposit||v.amount_minor!==s.amount||!uuid(v.journal_id)||typeof v.replayed!=='boolean'||v.journal_posted!==true||v.verifies_settlement!==false)throw Error('Transfer receipt does not match the saved request.');return v}
function canonical(value:unknown):string{if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';if(value&&typeof value==='object')return '{'+Object.entries(value).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>JSON.stringify(k)+':'+canonical(v)).join(',')+'}';return JSON.stringify(value)}
export function readDepositTransferStatus(value:unknown,r:DepositTransferRequest){checked(r);const v=obj(value),s=r.selection.scope;if(v.schema_version!==1||v.tenant_id!==s.tenant||v.property_id!==s.property||v.actor_id!==s.actor||v.request_id!==r.id||typeof v.found!=='boolean'||typeof v.cancelled!=='boolean'||typeof v.journal_reversed!=='boolean'||(v.found&&v.cancelled))throw Error('Transfer recovery scope changed.');if(!v.found){if(v.result!==null||v.review!==null||v.journal_reversed)throw Error('Invalid transfer recovery.');return {state:v.cancelled?'cancelled' as const:'missing' as const,result:null,reversed:false}}if(canonical(v.review)!==canonical(r.review))throw Error('Recovered transfer has a different review.');return {state:'posted' as const,result:readDepositTransferReceipt(v.result,r),reversed:v.journal_reversed}}
type Store=Pick<Storage,'getItem'|'setItem'|'removeItem'>;
function storageKey(scope:HandoffScope,deposit:string){if(![...Object.values(scope),deposit].every(uuid))throw Error('Invalid transfer storage scope.');return 'irp.deposit.transfer.v1:'+[scope.tenant,scope.property,scope.actor].join(':')+':'+deposit}
export function retainDepositTransfer(store:Store,r:DepositTransferRequest){checked(r);const key=storageKey(r.selection.scope,r.selection.deposit),prior=store.getItem(key);if(prior!==null&&canonical(JSON.parse(prior))!==canonical(r))throw Error('Recover or cancel the previous transfer first.');store.setItem(key,JSON.stringify(r));if(store.getItem(key)!==JSON.stringify(r))throw Error('Unable to retain transfer request.');}
export function restoreDepositTransfer(store:Store,scope:HandoffScope,deposit:string){const raw=store.getItem(storageKey(scope,deposit));if(raw===null)return null;const r=JSON.parse(raw) as DepositTransferRequest;checked(r);if(canonical(r.selection.scope)!==canonical(scope)||r.selection.deposit!==deposit)throw Error('Saved transfer belongs to another workspace.');return r}
export function clearDepositTransfer(store:Store,r:DepositTransferRequest,status:unknown){const parsed=readDepositTransferStatus(status,r);if(parsed.state==='missing')throw Error('Check or cancel the transfer before clearing it.');const key=storageKey(r.selection.scope,r.selection.deposit),prior=restoreDepositTransfer(store,r.selection.scope,r.selection.deposit);if(prior&&canonical(prior)!==canonical(r))throw Error('Saved transfer changed.');store.removeItem(key);return parsed}
